import{a as e,i as t,r as n,t as r}from"./app-DbTmPHyY.js";var i=JSON.parse(`{"path":"/%E7%AC%AC16%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E9%87%87%E8%B4%AD%E7%AE%A1%E7%90%86/16.1%20%E9%87%87%E8%B4%AD%E8%A7%84%E5%88%92.html","title":"16.1 采购规划","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第16章 项目采购管理/16.1 采购规划.md"}`),a={name:`16.1 采购规划.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_16-1-采购规划" tabindex="-1"><a class="header-anchor" href="#_16-1-采购规划"><span>16.1 采购规划</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>采购规划是指确定项目采购需求，制定采购计划的过程。</p><h2 id="采购规划的输入" tabindex="-1"><a class="header-anchor" href="#采购规划的输入"><span>采购规划的输入</span></a></h2><h3 id="_1-项目章程" tabindex="-1"><a class="header-anchor" href="#_1-项目章程"><span>1. 项目章程</span></a></h3><ul><li>项目目标和范围</li></ul><h3 id="_2-项目范围说明书" tabindex="-1"><a class="header-anchor" href="#_2-项目范围说明书"><span>2. 项目范围说明书</span></a></h3><ul><li>项目可交付成果</li></ul><h3 id="_3-进度计划" tabindex="-1"><a class="header-anchor" href="#_3-进度计划"><span>3. 进度计划</span></a></h3><ul><li>项目进度安排</li></ul><h3 id="_4-成本基准" tabindex="-1"><a class="header-anchor" href="#_4-成本基准"><span>4. 成本基准</span></a></h3><ul><li>项目预算</li></ul><h2 id="采购规划的输出" tabindex="-1"><a class="header-anchor" href="#采购规划的输出"><span>采购规划的输出</span></a></h2><h3 id="_1-采购管理计划" tabindex="-1"><a class="header-anchor" href="#_1-采购管理计划"><span>1. 采购管理计划</span></a></h3><ul><li>描述如何管理采购过程</li><li>包括采购策略、合同类型、采购流程</li></ul><h3 id="_2-采购工作说明书-sow" tabindex="-1"><a class="header-anchor" href="#_2-采购工作说明书-sow"><span>2. 采购工作说明书（SOW）</span></a></h3><ul><li>详细描述采购需求</li><li>包括技术要求、交付要求、验收标准</li></ul><h3 id="_3-采购文件" tabindex="-1"><a class="header-anchor" href="#_3-采购文件"><span>3. 采购文件</span></a></h3><ul><li>招标公告、招标文件</li><li>用于邀请供应商投标</li></ul><h2 id="采购规划的步骤" tabindex="-1"><a class="header-anchor" href="#采购规划的步骤"><span>采购规划的步骤</span></a></h2><h3 id="_1-采购需求分析" tabindex="-1"><a class="header-anchor" href="#_1-采购需求分析"><span>1. 采购需求分析</span></a></h3><ul><li>确定项目所需的采购内容</li><li>分析采购需求的必要性</li></ul><h3 id="_2-采购策略制定" tabindex="-1"><a class="header-anchor" href="#_2-采购策略制定"><span>2. 采购策略制定</span></a></h3><ul><li>确定采购方式（招标、询价、直接采购）</li><li>制定采购流程</li></ul><h3 id="_3-合同类型选择" tabindex="-1"><a class="header-anchor" href="#_3-合同类型选择"><span>3. 合同类型选择</span></a></h3><ul><li>根据采购内容选择合同类型</li><li>例如：固定总价合同、成本补偿合同、工时材料合同</li></ul><h3 id="_4-采购文件编制" tabindex="-1"><a class="header-anchor" href="#_4-采购文件编制"><span>4. 采购文件编制</span></a></h3><ul><li>编制采购文件</li><li>明确采购要求和评估标准</li></ul><h2 id="合同类型" tabindex="-1"><a class="header-anchor" href="#合同类型"><span>合同类型</span></a></h2><h3 id="_1-固定总价合同" tabindex="-1"><a class="header-anchor" href="#_1-固定总价合同"><span>1. 固定总价合同</span></a></h3><ul><li><strong>特点</strong>：总价固定</li><li><strong>适用</strong>：范围明确、风险较低的项目</li><li><strong>风险</strong>：卖方承担成本超支风险</li></ul><h3 id="_2-成本补偿合同" tabindex="-1"><a class="header-anchor" href="#_2-成本补偿合同"><span>2. 成本补偿合同</span></a></h3><ul><li><strong>特点</strong>：实报实销加利润</li><li><strong>适用</strong>：范围不确定、风险较高的项目</li><li><strong>风险</strong>：买方承担成本超支风险</li></ul><h3 id="_3-工时材料合同" tabindex="-1"><a class="header-anchor" href="#_3-工时材料合同"><span>3. 工时材料合同</span></a></h3><ul><li><strong>特点</strong>：按工时和材料费用结算</li><li><strong>适用</strong>：范围不确定、需要灵活调整的项目</li><li><strong>风险</strong>：双方共同承担风险</li></ul><h2 id="采购规划的注意事项" tabindex="-1"><a class="header-anchor" href="#采购规划的注意事项"><span>采购规划的注意事项</span></a></h2><h3 id="_1-明确需求" tabindex="-1"><a class="header-anchor" href="#_1-明确需求"><span>1. 明确需求</span></a></h3><ul><li>确保采购需求明确</li><li>避免后续变更</li></ul><h3 id="_2-选择合适合同类型" tabindex="-1"><a class="header-anchor" href="#_2-选择合适合同类型"><span>2. 选择合适合同类型</span></a></h3><ul><li>根据项目特点选择合同类型</li><li>平衡风险和成本</li></ul><h3 id="_3-合规性" tabindex="-1"><a class="header-anchor" href="#_3-合规性"><span>3. 合规性</span></a></h3><ul><li>遵守采购法规</li><li>确保采购过程公平公正</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>采购规划的步骤</strong></li><li><strong>合同类型</strong></li><li><strong>采购工作说明书的内容</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>采购规划定需求，策略合同类型要选对，SOW要详细</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：以下哪种合同类型适用于范围明确、风险较低的项目？ A. 固定总价合同 B. 成本补偿合同 C. 工时材料合同 D. 成本加利润合同</p><p><strong>答案</strong>：A</p><p><strong>解析</strong>：固定总价合同适用于范围明确、风险较低的项目，卖方承担成本超支风险。</p>`,50)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};